select case when year(s.started_at) < 2024 then 'before_2024' when year(s.started_at) = 2024 then '2024' else 'after_2024' end started_cohort, min(we.duration_sec) min_duration_sec, max(we.duration_sec) max_duration_sec from web_events we left join sessions s on we.session_id = s.id where we.page <> '/home' group by case when year(s.started_at) < 2024 then 'before_2024' when year(s.started_at) = 2024 then '2024' else 'after_2024' end having min_duration_sec >= 320 order by min_duration_sec;
